import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.imageio.ImageIO;
import javax.swing.JEditorPane;
import javax.swing.SwingUtilities;
import javax.swing.text.html.HTMLEditorKit;
import org.commonmark.Extension;
import org.commonmark.ext.gfm.tables.TableBlock;
import org.commonmark.ext.gfm.tables.TablesExtension;
import org.commonmark.node.FencedCodeBlock;
import org.commonmark.node.Node;
import org.commonmark.parser.Parser;
import org.commonmark.renderer.NodeRenderer;
import org.commonmark.renderer.html.HtmlNodeRendererContext;
import org.commonmark.renderer.html.HtmlRenderer;

/** Isolated layout probe. Deliberately contains no IntelliJ API or model invocation. */
public final class SwingMarkdownProbe {
    private static final String CODE = "// 课程代码样例\nint count = 1;\nString label = \"total < 10\";\n";
    private static final Map<String, String> FIXTURE_COLORS = Map.of(
        "comment", "#63845A", "keyword", "#0033B3", "number", "#1750EB", "string", "#067D17");

    public static void main(String[] args) throws Exception {
        Path base = Path.of(args[0]);
        String markdown = Files.readString(base.resolve("fixture.md"), StandardCharsets.UTF_8);
        List<Extension> extensions = List.of(TablesExtension.create());
        Node ast = Parser.builder().extensions(extensions).build().parse(markdown);
        if (count(ast, FencedCodeBlock.class) != 1 || count(ast, TableBlock.class) != 1) {
            throw new IllegalStateException("Expected exactly one code fence and one table");
        }
        HtmlRenderer renderer = HtmlRenderer.builder().extensions(extensions)
            .escapeHtml(true).sanitizeUrls(true)
            .nodeRendererFactory(context -> new FixtureCodeRenderer(context)).build();
        String body = renderer.render(ast);
        if (body.contains("<script>")) throw new IllegalStateException("Raw HTML was not escaped");
        String html = "<html><body>" + body + "</body></html>";
        Files.writeString(base.resolve("rendered.html"), html, StandardCharsets.UTF_8);
        BufferedImage[] pixels = new BufferedImage[1];
        String[] visibleText = new String[1];
        SwingUtilities.invokeAndWait(() -> {
            HTMLEditorKit kit = new HTMLEditorKit();
            kit.getStyleSheet().addRule("body { font-family: 'Microsoft YaHei'; font-size: 12pt; color: #202020; background: #ffffff; margin: 16px; }");
            kit.getStyleSheet().addRule("pre { font-family: Consolas; font-size: 12pt; background: #f4f4f4; }");
            kit.getStyleSheet().addRule("table { border-collapse: collapse; }");
            kit.getStyleSheet().addRule("td, th { border: 1px solid #b0b0b0; padding: 6px; }");
            JEditorPane pane = new JEditorPane();
            pane.setEditorKit(kit);
            pane.setEditable(false);
            pane.setText(html);
            pane.setSize(850, 16000);
            int height = pane.getPreferredSize().height;
            pane.setSize(850, height);
            pixels[0] = new BufferedImage(850, height, BufferedImage.TYPE_INT_RGB);
            Graphics2D graphics = pixels[0].createGraphics();
            graphics.setColor(Color.WHITE);
            graphics.fillRect(0, 0, 850, height);
            pane.printAll(graphics);
            graphics.dispose();
            pane.selectAll();
            visibleText[0] = pane.getSelectedText();
        });
        if (!visibleText[0].contains("int count = 1;") || !visibleText[0].contains("total < 10")) {
            throw new IllegalStateException("Code text lost in Swing document");
        }
        StringBuilder counts = new StringBuilder();
        for (var entry : FIXTURE_COLORS.entrySet()) {
            int color = Color.decode(entry.getValue()).getRGB();
            int matched = 0;
            for (int y = 0; y < pixels[0].getHeight(); y++) {
                for (int x = 0; x < pixels[0].getWidth(); x++) {
                    if (pixels[0].getRGB(x, y) == color) matched++;
                }
            }
            if (matched == 0) throw new IllegalStateException("Fixture color missing: " + entry.getKey());
            if (!counts.isEmpty()) counts.append(",");
            counts.append("\"").append(entry.getKey()).append("\":").append(matched);
        }
        ImageIO.write(pixels[0], "png", base.resolve("rendered.png").toFile());
        Files.writeString(base.resolve("visible-text.txt"), visibleText[0], StandardCharsets.UTF_8);
        String result = "{\"status\":\"success\",\"width\":850,\"height\":" + pixels[0].getHeight()
            + ",\"fencedCodeBlocks\":1,\"tables\":1,\"fixtureColorPixels\":{" + counts
            + "},\"colorsAreSynthetic\":true,\"intellijRuntimeExecuted\":false}";
        Files.writeString(base.resolve("result.json"), result, StandardCharsets.UTF_8);
        System.out.println(result);
    }

    private static long count(Node node, Class<? extends Node> type) {
        long total = type.isInstance(node) ? 1 : 0;
        for (Node child = node.getFirstChild(); child != null; child = child.getNext()) total += count(child, type);
        return total;
    }

    private static String escape(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
    }

    private record FixtureCodeRenderer(HtmlNodeRendererContext context) implements NodeRenderer {
        public Set<Class<? extends Node>> getNodeTypes() { return Set.of(FencedCodeBlock.class); }
        public void render(Node node) {
            FencedCodeBlock fence = (FencedCodeBlock) node;
            if (!fence.getInfo().equals("java") || !fence.getLiteral().equals(CODE)) {
                throw new IllegalStateException("Unexpected fixture code content");
            }
            String html = span("comment", "// 课程代码样例") + "\n"
                + span("keyword", "int") + " count = " + span("number", "1") + ";\n"
                + "String label = " + span("string", "\"total < 10\"") + ";\n";
            context.getWriter().raw("<pre><code>" + html + "</code></pre>\n");
        }
        private static String span(String category, String text) {
            return "<span style=\"color:" + FIXTURE_COLORS.get(category) + "\">" + escape(text) + "</span>";
        }
    }
}
